+'use strict';
+
+const db = require('../../database');
+const batch = require('../../batch');
+
+module.exports = {
+	name: 'Set user chat allow list to the users following if they turned on restrict chat',
+	timestamp: Date.UTC(2025, 3, 10),
+	method: async function () {
+		const { progress } = this;
+		progress.total = await db.sortedSetCard('users:joindate');
+
+		await batch.processSortedSet('users:joindate', async (uids) => {
+			const settings = await db.getObjects(uids.map(uid => `user:${uid}:settings`));
+			const restricted = uids.filter((uid, i) => settings[i] && parseInt(settings[i].restrictChat, 10) === 1);
