+				const following = await db.getSortedSetsMembers(restricted.map(uid => `following:${uid}`));
+				const bulkSet = restricted.map((uid, i) => {
+					const existing = settings[uids.indexOf(uid)];
+					let current = [];
+					try {
+						current = JSON.parse(existing.chatAllowList || '[]');
+					} catch (e) {
+						current = [];
+					}
+					if (!Array.isArray(current)) {
+						current = [];
+					}
+					const merged = Array.from(new Set([...current.map(String), ...(following[i] || []).map(String)]));
+					return [`user:${uid}:settings`, { chatAllowList: JSON.stringify(merged) }];
+				});
+				await db.setObjectBulk(bulkSet);
+			}
+			progress.incr(uids.length);
+		}, {
+			batch: 500,
+		});
+	},
+};
