+import { useState } from "react";
+
+import {
+    VoiceBroadcastInfoState,
+    VoiceBroadcastRecording,
+    VoiceBroadcastRecordingEvent,
+} from "..";
+import { useTypedEventEmitter } from "../../hooks/useEventEmitter";
+import { MatrixClientPeg } from "../../MatrixClientPeg";
+
+export const useVoiceBroadcastRecording = (recording: VoiceBroadcastRecording) => {
+    const client = MatrixClientPeg.get();
+    const room = client.getRoom(recording.infoEvent.getRoomId());
+    const stopRecording = () => {
+        recording.stop();
+    };
+
+    const [live, setLive] = useState(recording.state === VoiceBroadcastInfoState.Started);
+    useTypedEventEmitter(
+        recording,
+        VoiceBroadcastRecordingEvent.StateChanged,
+        (state: VoiceBroadcastInfoState) => {
+            setLive(state !== VoiceBroadcastInfoState.Stopped);
+        },
+    );
+
+    return {
+        live,
+        sender: recording.infoEvent.sender,
+        senderId: recording.infoEvent.getSender(),
+        roomName: room?.name,
+        stopRecording,
+    };
+};
