+    !is_eqtype(type, prev_type, NULL, opt))
+    return ffi_conflict(c, call, prev, f_name, "return type");
+
+  ast_t* decl = (ast_t*)ast_data(call);
+  ast_t* prev_decl = (ast_t*)ast_data(prev);
