--- a/src/libponyc/expr/array.c
+++ b/src/libponyc/expr/array.c
@@ -11,6 +11,264 @@
 #include "../type/alias.h"
 #include "../type/assemble.h"
 #include "../type/subtype.h"
+#include "ponyassert.h"
+
+static size_t child_index(ast_t* parent, ast_t* child)
+{
+  size_t i = 0;
+  for(ast_t* p = ast_child(parent); p != NULL; p = ast_sibling(p), i++)
+  {
+    if(p == child)
+      return i;
+  }
+  return (size_t)-1;
+}
+
+static ast_t* dup_type(ast_t* type)
+{
+  if((type == NULL) || (ast_id(type) == TK_NONE))
+    return NULL;
+  return ast_dup(type);
+}
+
+static ast_t* assign_target_type(pass_opt_t* opt, ast_t* left)
+{
+  switch(ast_id(left))
+  {
+    case TK_LET:
+    case TK_VAR:
+      return dup_type(ast_childidx(left, 1));
+
+    case TK_VARREF:
+    case TK_LETREF:
+    {
+      ast_t* def = (ast_t*)ast_data(left);
+      if(def == NULL)
+        return NULL;
+      switch(ast_id(def))
+      {
+        case TK_VAR:
+        case TK_LET:
+          return dup_type(ast_childidx(def, 1));
+        default: {}
+      }
+      return NULL;
+    }
+
+    case TK_DOT:
+    {
+      AST_GET_CHILDREN(left, obj, field_id);
+      if((ast_id(obj) != TK_THIS) || (ast_id(field_id) != TK_ID) ||
+        (opt->check.frame->type == NULL))
+        return NULL;
+      ast_t* def = ast_get(opt->check.frame->type, ast_name(field_id), NULL);
+      if(def == NULL)
+        return NULL;
+      switch(ast_id(def))
+      {
+        case TK_FVAR:
+        case TK_FLET:
+        case TK_EMBED:
+          return dup_type(ast_childidx(def, 1));
+        default: {}
+      }
+      return NULL;
+    }
+
+    default: {}
+  }
+  return NULL;
+}
+
+// Get the function type of the receiver of a call, type checking the
+// receiver early if necessary.
+static ast_t* call_funtype(pass_opt_t* opt, ast_t* call)
+{
+  if((call == NULL) || (ast_id(call) != TK_CALL))
+    return NULL;
+
+  ast_t* lhs = ast_childidx(call, 3);
+  if(ast_visit(&lhs, pass_pre_expr, pass_expr, opt, PASS_EXPR) != AST_OK)
+    return NULL;
+
+  ast_t* type = ast_type(lhs);
+  if((type == NULL) || (ast_id(type) != TK_FUNTYPE))
+    return NULL;
+
+  // Uninferred type parameters, we can't use the parameter types.
+  if(ast_id(ast_childidx(type, 1)) != TK_NONE)
+    return NULL;
+
+  return type;
+}
+
+ast_t* find_antecedent_type(pass_opt_t* opt, ast_t* ast)
+{
+  ast_t* parent = ast_parent(ast);
+  if(parent == NULL)
+    return NULL;
+
+  switch(ast_id(parent))
+  {
+    case TK_SEQ:
+    {
+      ast_t* gp = ast_parent(parent);
+      if((gp != NULL) && (ast_id(gp) == TK_ARRAY) &&
+        (ast_childidx(gp, 1) == parent))
+        return dup_type(ast_child(gp));
+
+      if(ast_sibling(ast) != NULL)
+        return NULL;
+
+      return find_antecedent_type(opt, parent);
+    }
+
+    case TK_IF:
+    {
+      size_t i = child_index(parent, ast);
+      if((i == 1) || (i == 2))
+        return find_antecedent_type(opt, parent);
+      return NULL;
+    }
+
+    case TK_TRY:
+    case TK_TRY_NO_CHECK:
+    {
+      size_t i = child_index(parent, ast);
+      if((i == 0) || (i == 1))
+        return find_antecedent_type(opt, parent);
+      return NULL;
+    }
+
+    case TK_ASSIGN:
+      if(ast_child(parent) != ast)
+        return NULL;
+      return assign_target_type(opt, ast_childidx(parent, 1));
+
+    case TK_FVAR:
+    case TK_FLET:
+    case TK_EMBED:
+    case TK_PARAM:
+    case TK_LAMBDACAPTURE:
+      if(ast_childidx(parent, 2) != ast)
+        return NULL;
+      return dup_type(ast_childidx(parent, 1));
+
+    case TK_RETURN:
+    {
+      ast_t* method = opt->check.frame->method;
+      if((method == NULL) || (ast_id(method) != TK_FUN))
+        return NULL;
+      return dup_type(ast_childidx(method, 4));
+    }
+
+    case TK_FUN:
+      if(ast_childidx(parent, 6) != ast)
+        return NULL;
+      return dup_type(ast_childidx(parent, 4));
+
+    case TK_POSITIONALARGS:
+    {
+      size_t i = child_index(parent, ast);
+      ast_t* funtype = call_funtype(opt, ast_parent(parent));
+      if(funtype == NULL)
+        return NULL;
+      ast_t* param = ast_childidx(ast_childidx(funtype, 2), i);
+      if((param == NULL) || (ast_id(param) != TK_PARAM))
+        return NULL;
+      return dup_type(ast_childidx(param, 1));
+    }
+
+    case TK_NAMEDARG:
+    case TK_UPDATEARG:
+    {
+      if(ast_childidx(parent, 1) != ast)
+        return NULL;
+      ast_t* namedargs = ast_parent(parent);
+      if((namedargs == NULL) || (ast_id(namedargs) != TK_NAMEDARGS))
+        return NULL;
+      ast_t* funtype = call_funtype(opt, ast_parent(namedargs));
+      if(funtype == NULL)
+        return NULL;
+      const char* name = ast_name(ast_child(parent));
+      for(ast_t* p = ast_child(ast_childidx(funtype, 2)); p != NULL;
+        p = ast_sibling(p))
+      {
+        if((ast_id(p) == TK_PARAM) && (ast_name(ast_child(p)) == name))
+          return dup_type(ast_childidx(p, 1));
+      }
+      return NULL;
+    }
+
+    default: {}
+  }
+
+  return NULL;
+}
+
+// Find the element type of an Array type within the given antecedent type.
+// Returns NULL if there is no unambiguous Array type.
+static ast_t* find_array_elem_type(ast_t* type, bool* ambiguous)
+{
+  switch(ast_id(type))
+  {
+    case TK_NOMINAL:
+    {
+      if(ast_name(ast_childidx(type, 1)) != stringtab("Array"))
+        return NULL;
+      ast_t* typeargs = ast_childidx(type, 2);
+      if(ast_id(typeargs) != TK_TYPEARGS)
+        return NULL;
+      return ast_child(typeargs);
+    }
+
+    case TK_UNIONTYPE:
+    case TK_ISECTTYPE:
+    {
+      ast_t* found = NULL;
+      for(ast_t* c = ast_child(type); c != NULL; c = ast_sibling(c))
+      {
+        ast_t* r = find_array_elem_type(c, ambiguous);
+        if(r != NULL)
+        {
+          if(found != NULL)
+            *ambiguous = true;
+          found = r;
+        }
+      }
+      return found;
+    }
+
+    case TK_ARROW:
+      return find_array_elem_type(ast_childidx(type, 1), ambiguous);
+
+    default: {}
+  }
+  return NULL;
+}
+
+bool expr_pre_array(pass_opt_t* opt, ast_t** astp)
+{
+  ast_t* ast = *astp;
+  pony_assert(ast_id(ast) == TK_ARRAY);
+  ast_t* type_spec = ast_child(ast);
+
+  if(ast_id(type_spec) != TK_NONE)
+    return true;
+
+  ast_t* antecedent = find_antecedent_type(opt, ast);
+  if(antecedent == NULL)
+    return true;
+
+  bool ambiguous = false;
+  ast_t* elem = find_array_elem_type(antecedent, &ambiguous);
+
+  if((elem != NULL) && !ambiguous)
+    ast_replace(&type_spec, ast_dup(elem));
+
+  ast_free_unattached(antecedent);
+  return true;
+}

