+// loadPrRequiredChecks fetches all status checks of a pull request along with whether they are required.
+func loadPrRequiredChecks(client *http.Client, repo ghrepo.Interface, pr *api.PullRequest) error {
+	type response struct {
+		Node *api.PullRequest
+	}
+
+	query := fmt.Sprintf(`
+	query PullRequestStatusChecks($id: ID!, $endCursor: String) {
+		node(id: $id) {
+			...on PullRequest {
+				%s
+			}
+		}
+	}`, api.RequiredStatusCheckRollupGraphQL("$id", "$endCursor"))
+
+	variables := map[string]interface{}{
+		"id": pr.ID,
+	}
+
+	apiClient := api.NewClientFromHTTP(client)
+	first := true
+	for {
+		var resp response
+		err := apiClient.GraphQL(repo.RepoHost(), query, variables, &resp)
+		if err != nil {
+			return err
+		}
+		if resp.Node == nil || len(resp.Node.StatusCheckRollup.Nodes) == 0 {
+			if first {
+				pr.StatusCheckRollup.Nodes = nil
+			}
+			return nil
+		}
+
+		if first {
+			pr.StatusCheckRollup = resp.Node.StatusCheckRollup
+			first = false
+		} else {
+			contexts := &pr.StatusCheckRollup.Nodes[0].Commit.StatusCheckRollup.Contexts
+			contexts.Nodes = append(contexts.Nodes, resp.Node.StatusCheckRollup.Nodes[0].Commit.StatusCheckRollup.Contexts.Nodes...)
+		}
+
+		result := resp.Node.StatusCheckRollup.Nodes[0].Commit.StatusCheckRollup.Contexts
+		if !result.PageInfo.HasNextPage {
+			break
+		}
+		variables["endCursor"] = result.PageInfo.EndCursor
+	}
+
+	pr.StatusCheckRollup.Nodes[0].Commit.StatusCheckRollup.Contexts.PageInfo.HasNextPage = false
+	return nil
+}
+
 type NotFoundError struct {
 	error
 }

