+package com.fasterxml.jackson.databind.node;
+
+import com.fasterxml.jackson.annotation.JsonRootName;
+import com.fasterxml.jackson.databind.*;
+
+// [databind#4047]: ObjectMapper.valueToTree() should honor WRAP_ROOT_VALUE
+public class ValueToTreeWithRootName4047Test extends BaseMapTest
+{
+    @JsonRootName("event")
+    static class Event {
+        public Long id = 1L;
+        public String name = "foo";
+    }
+
+    public void testValueToTreeWithWrapRootValue() throws Exception
+    {
+        ObjectMapper mapper = jsonMapperBuilder()
+                .enable(SerializationFeature.WRAP_ROOT_VALUE)
+                .build();
+        Event value = new Event();
+        JsonNode tree = mapper.valueToTree(value);
+        assertEquals(mapper.writeValueAsString(value), tree.toString());
+        assertEquals(a2q("{'event':{'id':1,'name':'foo'}}"), tree.toString());
+    }
+
+    public void testValueToTreeWithoutWrapRootValue() throws Exception
+    {
+        ObjectMapper mapper = newJsonMapper();
+        JsonNode tree = mapper.valueToTree(new Event());
+        assertEquals(a2q("{'id':1,'name':'foo'}"), tree.toString());
+    }
+}

