+/**
+ * Returns true if the expression contains an `await` (or `for await`) that is not
+ * nested inside a function boundary, i.e. evaluating it requires an async context.
+ * @param {any} node
+ * @returns {boolean}
+ */
+export function is_expression_async(node) {
+	if (node === null || typeof node !== 'object') return false;
+	if (Array.isArray(node)) return node.some(is_expression_async);
+	if (typeof node.type !== 'string') return false;
+
+	switch (node.type) {
+		case 'AwaitExpression':
+			return true;
+		case 'ForOfStatement':
+			if (node.await) return true;
+			break;
+		case 'FunctionExpression':
+		case 'FunctionDeclaration':
+		case 'ArrowFunctionExpression':
+			return false;
+	}
+
+	for (const key in node) {
+		if (
+			key === 'metadata' ||
+			key === 'parent' ||
+			key === 'loc' ||
+			key === 'start' ||
+			key === 'end'
+		) {
+			continue;
+		}
+		const value = node[key];
+		if (value && typeof value === 'object' && is_expression_async(value)) return true;
+	}
+	return false;
+}
