+import * as React from 'react';
+import { expect } from 'chai';
+import { createRenderer, describeConformance } from 'test/utils';
+import { CssVarsProvider, extendTheme } from '@mui/material-next/styles';
+import Badge, { badgeClasses as classes } from '@mui/material-next/Badge';
+
+function findBadge(container) {
+  return container.firstChild.querySelector('span');
+}
+
+describe('<Badge />', () => {
+  const { render } = createRenderer();
+
+  describeConformance(
+    <Badge className="testClassName" badgeContent={10}>
+      <div />
+    </Badge>,
+    () => ({
+      classes,
+      inheritComponent: 'span',
+      render,
+      refInstanceof: window.HTMLSpanElement,
+      muiName: 'MuiBadge',
+      testVariantProps: { color: 'secondary', variant: 'dot' },
+      ThemeProvider: CssVarsProvider,
+      createTheme: extendTheme,
+      slots: {
+        root: { expectedClassName: classes.root },
+        badge: { expectedClassName: classes.badge },
+      },
+      skip: ['componentsProp'],
+    }),
+  );
+
+  it('renders children and badgeContent', () => {
+    const { container, getByText } = render(
+      <Badge badgeContent={1}>
+        <div>child</div>
+      </Badge>,
+    );
+    expect(getByText('child')).not.to.equal(null);
+    expect(findBadge(container)).to.have.text('1');
+  });
+
+  it('applies error color by default', () => {
+    const { container } = render(<Badge badgeContent={1} />);
+    expect(findBadge(container)).to.have.class(classes.colorError);
+  });
+
+  it('caps the value with max', () => {
+    const { container } = render(<Badge badgeContent={1000} max={99} />);
+    expect(findBadge(container)).to.have.text('99+');
+  });
+
+  it('is invisible when badgeContent is 0 and showZero is false', () => {
+    const { container } = render(<Badge badgeContent={0} />);
+    expect(findBadge(container)).to.have.class(classes.invisible);
+  });
+
+  it('renders no content with dot variant', () => {
+    const { container } = render(<Badge badgeContent={10} variant="dot" />);
+    expect(findBadge(container)).to.have.class(classes.dot);
+    expect(findBadge(container)).to.have.text('');
+  });
+});
