+'use client';
+import * as React from 'react';
+import PropTypes from 'prop-types';
+import clsx from 'clsx';
+import { usePreviousProps, unstable_capitalize as capitalize } from '@mui/utils';
+import { useSlotProps, unstable_composeClasses as composeClasses } from '@mui/base';
+import useBadge from '@mui/base/useBadge';
+import styled from '../styles/styled';
+import useThemeProps from '../styles/useThemeProps';
+import badgeClasses, { getBadgeUtilityClass } from './badgeClasses';
+import { BadgeComponent, BadgeOwnerState, BadgeProps, BadgeTypeMap } from './Badge.types';
+
+const useUtilityClasses = (ownerState: BadgeOwnerState) => {
+  const { color, anchorOrigin, invisible, overlap, variant, classes = {} } = ownerState;
+
+  const slots = {
+    root: ['root'],
+    badge: [
+      'badge',
+      variant,
+      invisible && 'invisible',
+      `anchorOrigin${capitalize(anchorOrigin.vertical)}${capitalize(anchorOrigin.horizontal)}`,
+      `overlap${capitalize(overlap)}`,
+      `color${capitalize(color)}`,
+    ],
+  };
+
+  return composeClasses(slots, getBadgeUtilityClass, classes);
+};
+
+const BadgeRoot = styled('span', {
+  name: 'MuiBadge',
+  slot: 'Root',
+  overridesResolver: (props, styles) => styles.root,
+})({
+  position: 'relative',
+  display: 'inline-flex',
+  // For correct alignment with the text.
+  verticalAlign: 'middle',
+  flexShrink: 0,
+});
+
+const BadgeBadge = styled('span', {
+  name: 'MuiBadge',
+  slot: 'Badge',
+  overridesResolver: (props, styles) => {
+    const { ownerState } = props;
+
+    return [
+      styles.badge,
+      styles[ownerState.variant],
+      styles[
+        `anchorOrigin${capitalize(ownerState.anchorOrigin.vertical)}${capitalize(
+          ownerState.anchorOrigin.horizontal,
+        )}`
+      ],
+      styles[`overlap${capitalize(ownerState.overlap)}`],
+      styles[`color${capitalize(ownerState.color)}`],
+      ownerState.invisible && styles.invisible,
+    ];
+  },
+})<{ ownerState: BadgeOwnerState }>(({ theme, ownerState }) => {
+  const { vars: tokens } = theme;
+  const color = ownerState.color as string;
+  const onColorKey = `on${capitalize(color)}` as keyof typeof tokens.sys.color;
+  const { vertical, horizontal } = ownerState.anchorOrigin;
+  const isDot = ownerState.variant === 'dot';
+  const offset = ownerState.overlap === 'circular' ? '14%' : '0%';
+  const translateX = horizontal === 'right' ? '50%' : '-50%';
+  const translateY = vertical === 'top' ? '-50%' : '50%';
+
+  return {
+    '--md-comp-badge-size': isDot ? '6px' : '16px',
+    '--md-comp-badge-padding': isDot ? '0px' : '4px',
+    '--md-comp-badge-radius': tokens.sys.shape.corner.full,
+    '--md-comp-badge-color': (tokens.sys.color as any)[color],
+    '--md-comp-badge-text-color': (tokens.sys.color as any)[onColorKey],
+    '--md-comp-badge-offset': offset,
+    display: 'flex',
+    flexDirection: 'row',
+    flexWrap: 'wrap',
+    justifyContent: 'center',
+    alignContent: 'center',
+    alignItems: 'center',
+    position: 'absolute',
+    boxSizing: 'border-box',
+    fontFamily: tokens.sys.typescale.label.small.family,
+    fontWeight: tokens.sys.typescale.label.small.weight,
+    fontSize: theme.typography.pxToRem(theme.sys.typescale.label.small.size),
+    lineHeight: 1,
+    minWidth: 'var(--md-comp-badge-size)',
+    height: 'var(--md-comp-badge-size)',
+    padding: '0 var(--md-comp-badge-padding)',
+    borderRadius: 'var(--md-comp-badge-radius)',
+    backgroundColor: 'var(--md-comp-badge-color)',
+    color: 'var(--md-comp-badge-text-color)',
+    zIndex: 1, // Render the badge on top of potential ripples.
+    transition: theme.transitions.create('transform', {
+      easing: theme.transitions.easing.easeInOut,
+      duration: theme.transitions.duration.enteringScreen,
+    }),
+    [vertical]: 'var(--md-comp-badge-offset)',
+    [horizontal]: 'var(--md-comp-badge-offset)',
+    transform: `scale(1) translate(${translateX}, ${translateY})`,
+    transformOrigin: `${horizontal === 'right' ? '100%' : '0%'} ${
+      vertical === 'top' ? '0%' : '100%'
+    }`,
+    [`&.${badgeClasses.invisible}`]: {
+      transform: `scale(0) translate(${translateX}, ${translateY})`,
+    },
+    ...(ownerState.invisible && {
+      transition: theme.transitions.create('transform', {
+        easing: theme.transitions.easing.easeInOut,
+        duration: theme.transitions.duration.leavingScreen,
+      }),
+    }),
+  };
+});
+
+const Badge = React.forwardRef(function Badge<
+  BaseComponentType extends React.ElementType = BadgeTypeMap['defaultComponent'],
+>(inProps: BadgeProps<BaseComponentType>, ref: React.ForwardedRef<any>) {
+  const props = useThemeProps({ props: inProps, name: 'MuiBadge' });
+  const {
+    anchorOrigin: anchorOriginProp = {
+      vertical: 'top',
+      horizontal: 'right',
+    },
+    className,
+    classes: classesProp,
+    component,
+    children,
+    overlap: overlapProp = 'rectangular',
+    color: colorProp = 'error',
+    invisible: invisibleProp = false,
+    max: maxProp = 99,
+    badgeContent: badgeContentProp,
+    slots,
+    slotProps,
+    showZero = false,
+    variant: variantProp = 'standard',
+    ...other
+  } = props;
+
+  const {
+    badgeContent,
+    invisible: invisibleFromHook,
+    max,
+    displayValue: displayValueFromHook,
+  } = useBadge({
+    max: maxProp,
+    invisible: invisibleProp,
+    badgeContent: badgeContentProp,
+    showZero,
+  });
+
+  const prevProps = usePreviousProps({
+    anchorOrigin: anchorOriginProp,
+    color: colorProp,
+    overlap: overlapProp,
+    variant: variantProp,
+    badgeContent: badgeContentProp,
+  }) as Partial<BadgeProps>;
+
+  const invisible = invisibleFromHook || (badgeContent == null && variantProp !== 'dot');
+
+  const source: Partial<BadgeProps> = invisible ? prevProps ?? {} : props;
+  const {
+    color = colorProp,
+    overlap = overlapProp,
+    anchorOrigin = anchorOriginProp,
+    variant = variantProp,
+  } = source;
+
+  const displayValue = variant !== 'dot' ? displayValueFromHook : undefined;
+
+  const ownerState: BadgeOwnerState = {
+    ...props,
+    badgeContent,
+    invisible,
+    max,
+    displayValue,
+    showZero,
+    anchorOrigin,
+    color,
+    overlap,
+    variant,
+  };
+
+  const classes = useUtilityClasses(ownerState);
+
+  const RootSlot = slots?.root ?? BadgeRoot;
+  const BadgeSlot = slots?.badge ?? BadgeBadge;
+
+  const rootProps = useSlotProps({
+    elementType: RootSlot,
+    externalSlotProps: slotProps?.root,
+    externalForwardedProps: other,
+    additionalProps: {
+      ref,
+      as: component,
+    },
+    ownerState,
+    className: clsx(classes.root, className),
+  });
+
+  const badgeProps = useSlotProps({
+    elementType: BadgeSlot,
+    externalSlotProps: slotProps?.badge,
+    ownerState,
+    className: classes.badge,
+  });
+
+  return (
+    <RootSlot {...rootProps}>
+      {children}
+      <BadgeSlot {...badgeProps}>{displayValue}</BadgeSlot>
+    </RootSlot>
+  );
+}) as BadgeComponent;
+
+Badge.propTypes /* remove-proptypes */ = {
+  anchorOrigin: PropTypes.shape({
+    horizontal: PropTypes.oneOf(['left', 'right']).isRequired,
+    vertical: PropTypes.oneOf(['bottom', 'top']).isRequired,
+  }),
+  badgeContent: PropTypes.node,
+  children: PropTypes.node,
+  classes: PropTypes.object,
+  className: PropTypes.string,
+  color: PropTypes /* @typescript-to-proptypes-ignore */.oneOfType([
+    PropTypes.oneOf(['primary', 'secondary', 'tertiary', 'error']),
+    PropTypes.string,
+  ]),
+  component: PropTypes.elementType,
+  invisible: PropTypes.bool,
+  max: PropTypes.number,
+  overlap: PropTypes.oneOf(['circular', 'rectangular']),
+  showZero: PropTypes.bool,
+  slotProps: PropTypes.shape({
+    badge: PropTypes.oneOfType([PropTypes.func, PropTypes.object]),
+    root: PropTypes.oneOfType([PropTypes.func, PropTypes.object]),
+  }),
+  slots: PropTypes.shape({
+    badge: PropTypes.elementType,
+    root: PropTypes.elementType,
+  }),
+  sx: PropTypes.oneOfType([
+    PropTypes.arrayOf(PropTypes.oneOfType([PropTypes.func, PropTypes.object, PropTypes.bool])),
+    PropTypes.func,
+    PropTypes.object,
+  ]),
+  variant: PropTypes /* @typescript-to-proptypes-ignore */.oneOfType([
+    PropTypes.oneOf(['dot', 'standard']),
+    PropTypes.string,
+  ]),
+} as any;
+
+export default Badge;
