+import * as React from 'react';
+import { SlotComponentProps } from '@mui/base';
+import { SxProps } from '@mui/system';
+import { OverridableStringUnion, OverrideProps, OverridableComponent } from '@mui/types';
+import { Theme } from '../styles';
+import { BadgeClasses } from './badgeClasses';
+
+export interface BadgePropsVariantOverrides {}
+export interface BadgePropsColorOverrides {}
+export interface BadgeRootSlotPropsOverrides {}
+export interface BadgeBadgeSlotPropsOverrides {}
+
+export interface BadgeOrigin {
+  vertical: 'top' | 'bottom';
+  horizontal: 'left' | 'right';
+}
+
+export interface BadgeOwnProps {
+  /**
+   * The anchor of the badge.
+   * @default {
+   *   vertical: 'top',
+   *   horizontal: 'right',
+   * }
+   */
+  anchorOrigin?: BadgeOrigin;
+  /**
+   * The content rendered within the badge.
+   */
+  badgeContent?: React.ReactNode;
+  /**
+   * The badge will be added relative to this node.
+   */
+  children?: React.ReactNode;
+  /**
+   * Override or extend the styles applied to the component.
+   */
+  classes?: Partial<BadgeClasses>;
+  /**
+   * @ignore
+   */
+  className?: string;
+  /**
+   * The color of the component.
+   * @default 'error'
+   */
+  color?: OverridableStringUnion<
+    'primary' | 'secondary' | 'tertiary' | 'error',
+    BadgePropsColorOverrides
+  >;
+  /**
+   * If `true`, the badge is invisible.
+   * @default false
+   */
+  invisible?: boolean;
+  /**
+   * Max count to show.
+   * @default 99
+   */
+  max?: number;
+  /**
+   * Wrapped shape the badge should overlap.
+   * @default 'rectangular'
+   */
+  overlap?: 'rectangular' | 'circular';
+  /**
+   * Controls whether the badge is hidden when `badgeContent` is zero.
+   * @default false
+   */
+  showZero?: boolean;
+  /**
+   * The props used for each slot inside the Badge.
+   * @default {}
+   */
+  slotProps?: {
+    root?: SlotComponentProps<'span', BadgeRootSlotPropsOverrides, BadgeOwnerState>;
+    badge?: SlotComponentProps<'span', BadgeBadgeSlotPropsOverrides, BadgeOwnerState>;
+  };
+  /**
+   * The components used for each slot inside the Badge.
+   * @default {}
+   */
+  slots?: {
+    root?: React.ElementType;
+    badge?: React.ElementType;
+  };
+  /**
+   * The system prop that allows defining system overrides as well as additional CSS styles.
+   */
+  sx?: SxProps<Theme>;
+  /**
+   * The variant to use.
+   * @default 'standard'
+   */
+  variant?: OverridableStringUnion<'standard' | 'dot', BadgePropsVariantOverrides>;
+}
+
+export interface BadgeTypeMap<D extends React.ElementType = 'span', P = {}> {
+  props: P & BadgeOwnProps;
+  defaultComponent: D;
+}
+
+export type BadgeProps<
+  D extends React.ElementType = BadgeTypeMap['defaultComponent'],
+  P = {},
+> = OverrideProps<BadgeTypeMap<D, P>, D> & {
+  component?: React.ElementType;
+};
+
+export interface BadgeOwnerState extends BadgeProps {
+  anchorOrigin: BadgeOrigin;
+  color: NonNullable<BadgeOwnProps['color']>;
+  overlap: NonNullable<BadgeOwnProps['overlap']>;
+  variant: NonNullable<BadgeOwnProps['variant']>;
+  invisible: boolean;
+  max: number;
+  showZero: boolean;
+  displayValue: React.ReactNode;
+}
+
+export type BadgeComponent = OverridableComponent<BadgeTypeMap>;
